let simRunning=false,simInterval=null,opCount=0,s1=0,s2=0,s3=0,currentMethod='acoustic';function rI(a,b){return a+Math.floor(Math.random()*(b-a))}function rH(n){let s='';for(let i=0;i<n;i++)s+='0123456789abcdef'[Math.floor(Math.random()*16)];return s}
const OPS=["Acoustic ultrasonic", "EM emanation", "Thermal CPU mod", "Bridge rate", "Reed-Solomon", "SNR measured", "Distance est", "Sync pulse", "Fan modulation", "LED blink", "Power line", "Magnetic ch"];
function genOp(){return{type:currentMethod.toUpperCase().slice(0,4),data:OPS[rI(0,OPS.length)]+` [${rI(10,9999)}]`,status:'OK'}}let canvas,ctx,particles=[];function initCanvas(){canvas=$('appCanvas');if(!canvas)return;ctx=canvas.getContext('2d');canvas.width=canvas.offsetWidth*2;canvas.height=canvas.offsetHeight*2;ctx.scale(2,2)}
function drawCanvas(){if(!ctx)return;const w=canvas.offsetWidth,h=canvas.offsetHeight;ctx.fillStyle='rgba(10,10,26,0.12)';ctx.fillRect(0,0,w,h);const colors={acoustic:'#f59e0b',em:'#3b82f6',thermal:'#ef4444'};const col=colors[currentMethod]||'#3b82f6';particles.forEach((p,i)=>{p.x+=p.vx;p.y+=p.vy;p.life-=0.012;if(p.life<=0){particles.splice(i,1);return}ctx.beginPath();ctx.arc(p.x,p.y,p.r*p.life,0,Math.PI*2);ctx.fillStyle=col;ctx.globalAlpha=p.life*0.6;ctx.fill();ctx.globalAlpha=1;if(i>0&&i<particles.length){const prev=particles[i-1];ctx.beginPath();ctx.moveTo(prev.x,prev.y);ctx.lineTo(p.x,p.y);ctx.strokeStyle=col;ctx.globalAlpha=p.life*0.15;ctx.lineWidth=0.5;ctx.stroke();ctx.globalAlpha=1}});const pct=Math.min(opCount/80,1);ctx.fillStyle='rgba(0,0,0,0.3)';ctx.fillRect(10,h-12,w-20,6);ctx.fillStyle=col+'80';ctx.fillRect(10,h-12,(w-20)*pct,6);ctx.font='7px monospace';ctx.fillStyle='rgba(255,255,255,0.3)';ctx.textAlign='center';ctx.fillText(s2+' operations completed',w/2,h-2)}
function addParticles(){const w=canvas?canvas.offsetWidth:300,h=canvas?canvas.offsetHeight:200;for(let i=0;i<3;i++)particles.push({x:Math.random()*w*0.3,y:h/2+rI(-20,20),vx:1+Math.random()*2,vy:(Math.random()-0.5)*0.8,r:2+Math.random()*4,life:1});if(particles.length>200)particles.splice(0,50)}
function updateUI(){$('stat1').textContent=s1;$('stat2').textContent=s2;$('stat3').textContent=Math.round(s3/8);$('stat4').textContent=Math.min(Math.round(opCount/80*100),100)+'%'}
function addOpToList(op){const list=$('opList');if(!list)return;const d=document.createElement('div');d.className='op-item';d.innerHTML=`<span class="op-type">${op.type}</span><span class="op-data">${op.data}</span><span class="op-status">${op.status}</span>`;list.insertBefore(d,list.firstChild);if(list.children.length>100)list.removeChild(list.lastChild)}
function simTick(){const op=genOp();opCount++;s1++;s2+=rI(8,64);s3+=rI(8,64);addOpToList(op);addParticles();updateUI();log(`${op.type}: ${op.data}`,'tx')}
function startSim(){if(simRunning)return;simRunning=true;setStatus(true);$('startBtn').disabled=true;$('stopBtn').disabled=false;opCount=0;s1=0;s2=0;s3=0;particles=[];initCanvas();log(LANG[currentLang].simStarted,'success');simInterval=setInterval(simTick,500);requestAnimationFrame(function loop(){if(!simRunning)return;drawCanvas();requestAnimationFrame(loop)})}
function stopSim(){simRunning=false;if(simInterval)clearInterval(simInterval);setStatus(false);$('startBtn').disabled=false;$('stopBtn').disabled=true;log(LANG[currentLang].simStopped,'info')}
function init(){initSplash();const lw=$('logoWrap');if(lw)lw.innerHTML=LOGO_SVG;$('clearLogBtn').onclick=clearLog;$('copyLogBtn').onclick=copyLog;$('exportLogBtn').onclick=exportLog;initLogFilters();$('helpBtn').onclick=openHelp;$('helpCloseBtn').onclick=closeHelp;$('helpOverlay').onclick=closeHelp;initHelpTabs();$('settingsBtn').onclick=openSettings;$('settingsCloseBtn').onclick=closeSettings;$('settingsOverlay').onclick=closeSettings;$('logBtn').onclick=toggleLog;$('logCloseBtn').onclick=closeLog;initLogResize();const st=$('soundToggle');if(st){try{soundEnabled=localStorage.getItem('wdiy-sound')==='true'}catch{}st.checked=soundEnabled;st.addEventListener('change',()=>{soundEnabled=st.checked;try{localStorage.setItem('wdiy-sound',soundEnabled)}catch{}if(soundEnabled)playSound('click')})}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAllPanels()});$('langSelect').addEventListener('change',()=>setLanguage($('langSelect').value));$('themeSelect').addEventListener('change',()=>setTheme($('themeSelect').value));try{const sl=localStorage.getItem('wdiy-lang');const st2=localStorage.getItem('wdiy-theme');if(st2)setTheme(st2);if(sl)setLanguage(sl)}catch{}initHijriDate();$('startBtn').onclick=startSim;$('stopBtn').onclick=stopSim;document.querySelectorAll('.method-tab').forEach(tab=>{tab.addEventListener('click',()=>{document.querySelectorAll('.method-tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');currentMethod=tab.dataset.method;playSound('click')})});log(LANG[currentLang].ready,'success')}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
/* ═══════ RICH CANVAS — Airgap Bridge Visualizer ═══════ */
(function(){const CVS_ID='richVisCanvas';function ensureCanvas(){if(document.getElementById(CVS_ID))return document.getElementById(CVS_ID);const wrap=document.querySelector('.card');if(!wrap)return null;const card=document.createElement('div');card.className='card';card.innerHTML='<div class="card-header"><div class="card-title"><span class="icon">📻️</span> Airgap Bridge Visualizer</div></div>';const c=document.createElement('canvas');c.id=CVS_ID;c.style.cssText='width:100%;height:260px;border-radius:12px;background:#0a0a1a;display:block;margin-top:8px;';card.appendChild(c);wrap.parentNode.insertBefore(card,wrap.nextSibling);return c}let nodes=[],_raf=null,frame=0;function draw(){const c=document.getElementById(CVS_ID);if(!c){_raf=null;return}const x=c.getContext('2d');const W=c.width=c.offsetWidth*2,H=c.height=c.offsetHeight*2;x.scale(2,2);const w=W/2,h=H/2;x.fillStyle='rgba(10,10,26,0.1)';x.fillRect(0,0,w,h);frame++;const isR=typeof simRunning!=='undefined'&&simRunning;const colors={acoustic:'#f59e0b',em:'#3b82f6',thermal:'#ef4444'};const col=colors[typeof currentMethod!=='undefined'?currentMethod:'acoustic']||'#3b82f6';if(isR&&frame%5===0)nodes.push({x:Math.random()*w,y:Math.random()*h,r:2+Math.random()*4,alpha:1,pulse:0});nodes.forEach((n,i)=>{n.alpha-=0.004;n.pulse+=0.05;if(n.alpha<=0){nodes.splice(i,1);return}x.beginPath();x.arc(n.x,n.y,n.r+Math.sin(n.pulse)*2,0,Math.PI*2);x.fillStyle=col;x.globalAlpha=n.alpha*0.5;x.fill();x.globalAlpha=1});for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y,dist=Math.sqrt(dx*dx+dy*dy);if(dist<60){x.beginPath();x.moveTo(nodes[i].x,nodes[i].y);x.lineTo(nodes[j].x,nodes[j].y);x.strokeStyle=col;x.globalAlpha=0.08*(1-dist/60);x.lineWidth=0.5;x.stroke();x.globalAlpha=1}}if(nodes.length>100)nodes.splice(0,30);x.font='8px monospace';x.fillStyle='rgba(255,255,255,0.25)';x.textAlign='center';x.fillText('Airgap Bridge Visualizer',w/2,h-8);_raf=requestAnimationFrame(draw)}function boot(){const c=ensureCanvas();if(!c)return setTimeout(boot,500);if(!_raf)draw()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot()})();


// ── Code Tab Switching ──
document.addEventListener('click', function(e) {
  if (e.target.classList.contains('code-tab')) {
    var tabs = e.target.parentElement;
    tabs.querySelectorAll('.code-tab').forEach(function(t) { t.classList.remove('active'); });
    e.target.classList.add('active');
    var target = e.target.getAttribute('data-codetarget');
    var card = tabs.closest('.card');
    card.querySelectorAll('.code-display').forEach(function(d) { d.classList.add('hidden'); });
    var show = card.querySelector('#code-' + target);
    if (show) show.classList.remove('hidden');
  }
});

var DEMO_STEPS = [
  {i18n:'demo_s1', text:'Welcome! Let\'s explore this simulation together. Look at the main section above. 🔬', target:'#helpBtn', delay:3000},
  {i18n:'demo_s2', text:'Click the primary action button to start. Watch the visualization respond in real time! ⚡', target:'#settingsBtn', delay:3000},
  {i18n:'demo_s3', text:'Now change a setting — try a slider or dropdown. See how the output changes? 🔄', target:'#logBtn', delay:3000},
  {i18n:'demo_s4', text:'Check the results — the graphs and numbers show what\'s happening under the hood. 📊', target:'#simCanvas', delay:3000},
  {i18n:'demo_s5', text:'Awesome! 🎉 You\'ve got the basics. Try the Lab section below for deeper experiments!', target:'#mainCard', delay:3000},
];

// ── Demo Engine ──
var _demoStep = 0, _demoPlaying = false, _demoTimer = null;
var _demoSteps = (typeof DEMO_STEPS !== 'undefined') ? DEMO_STEPS : [];

function demoNav(dir) {
  _demoStep = Math.max(0, Math.min(_demoSteps.length - 1, _demoStep + dir));
  demoShow();
}

function demoToggle() {
  _demoPlaying = !_demoPlaying;
  var btn = document.getElementById('demoPlayBtn');
  if (btn) btn.innerHTML = _demoPlaying ? '⏸ <span data-i18n="demoPause">Pause</span>' : '▶ <span data-i18n="demoPlay">Play</span>';
  if (_demoPlaying) {
    demoShow();
    _demoTimer = setInterval(function() {
      if (_demoStep < _demoSteps.length - 1) { _demoStep++; demoShow(); }
      else { _demoPlaying = false; clearInterval(_demoTimer); var b = document.getElementById('demoPlayBtn'); if(b) b.innerHTML = '▶ <span data-i18n="demoPlay">Play</span>'; }
    }, 3000);
  } else {
    clearInterval(_demoTimer);
  }
}

function demoShow() {
  var step = _demoSteps[_demoStep];
  if (!step) return;
  var numEl = document.getElementById('demoCurrentStep');
  var narEl = document.getElementById('demoNarration');
  var barEl = document.getElementById('demoProgressBar');
  if (numEl) numEl.textContent = (_demoStep + 1) + '/' + _demoSteps.length;
  if (narEl) { narEl.setAttribute('data-i18n', step.i18n); narEl.textContent = step.text; if (typeof applyLang === 'function') applyLang(); }
  if (barEl) barEl.style.width = ((_demoStep + 1) / _demoSteps.length * 100) + '%';
  // Remove old highlights
  document.querySelectorAll('.demo-highlight').forEach(function(el) { el.classList.remove('demo-highlight'); });
  // Add highlight
  if (step.target) { var t = document.querySelector(step.target); if (t) { t.classList.add('demo-highlight'); t.scrollIntoView({behavior:'smooth', block:'center'}); } }
}

